template <>
inline Ark_RuntimeType runtimeType(const Ark_GestureType& value)
{
    switch (value.selector) {
        case 0: return runtimeType(value.value0);
        case 1: return runtimeType(value.value1);
        default: INTEROP_FATAL("Bad selector in Ark_GestureType: %d", value.selector);
    }
}
template <>
inline void WriteToString(std::string* result, const Ark_GestureType* value) {
    result->append("{");
    result->append(".selector=");
    result->append(std::to_string(value->selector));
    result->append(", ");
    // Ark_Gesture
    if (value->selector == 0) {
        result->append(".value0=");
        WriteToString(result, value->value0);
    }
    // Ark_CustomObject
    if (value->selector == 1) {
        result->append(".value1=");
        WriteToString(result, &value->value1);
    }
    result->append("}");
}
template <>
inline void WriteToString(std::string* result, const Opt_GestureType* value) {
    result->append("{.tag=");
    result->append(tagNameExact((Ark_Tag)(value->tag)));
    result->append(", .value=");
    if (value->tag != INTEROP_TAG_UNDEFINED) {
        WriteToString(result, &value->value);
    } else {
        Ark_Undefined undefined = { 0 };
        WriteToString(result, undefined);
    }
    result->append("}");
}
